const charges = $('Stripe charges 7d').first().json.data || [];
const refunds = $('Stripe refunds 7d').first().json.data || [];
const ga = ($('GA4 events 7d').first().json.rows || []).reduce((m, r) => { m[r.dimensionValues[0].value] = Number(r.metricValues[0].value); return m; }, {});
const paid = charges.filter(c => c.paid && !c.refunded);
const orders = paid.length;
const revenue = paid.reduce((s, c) => s + c.amount, 0) / 100;
const refundAmt = refunds.reduce((s, r) => s + r.amount, 0) / 100;
const aov = orders ? revenue / orders : 0;
const optinRate = ga.view_72 ? (ga.lead_72 || 0) / ga.view_72 : 0;
const refundRate = orders ? refunds.length / orders : 0;
const spend = Number($env.WEEKLY_AD_SPEND || 0); // replace with Google Ads / Meta API pulls when connected
const flags = [];
if (optinRate && optinRate < 0.20) flags.push('opt-in rate under 20%: fix the /72 page');
if (aov && aov < 30) flags.push('AOV under $30: check bump placement');
if (refundRate > 0.06) flags.push('refund rate over 6%: read the reasons');
const text = `Executor's Desk — week ending ${$now.toFormat('yyyy-LL-dd')}\n` +
`Page views /72: ${ga.view_72||0}  Opt-ins: ${ga.lead_72||0}  Opt-in rate: ${(optinRate*100).toFixed(1)}%\n` +
`Notebook page views: ${ga.view_notebook||0}  Checkouts started: ${ga.begin_checkout||0}\n` +
`Orders: ${orders}  Revenue: $${revenue.toFixed(2)}  AOV: $${aov.toFixed(2)}\n` +
`Refunds: ${refunds.length} ($${refundAmt.toFixed(2)})  Refund rate: ${(refundRate*100).toFixed(1)}%\n` +
`Ad spend (manual until APIs connected): $${spend.toFixed(2)}  Cost per opt-in: ${ga.lead_72 ? '$'+(spend/ga.lead_72).toFixed(2) : 'n/a'}\n` +
(flags.length ? `\nFlags:\n- ${flags.join('\n- ')}` : '\nNo flags.');
return [{ json: { text, row: [ $now.toFormat('yyyy-LL-dd'), spend, ga.view_72||0, ga.lead_72||0, orders, aov.toFixed(2), revenue.toFixed(2), refunds.length ] } }];
